/* ===================== personaggi ===================== */
const NAME={
na_santu:"Santu, il pastore corso",
na_bettina:"Bettina, la contadina lombarda",
na_denon:"Dominique Vivant Denon, il disegnatore",
na_giuseppina:"Giuseppina, l’imperatrice delle rose",
na_gaspard:"Gaspard, granatiere della Guardia",
na_beethoven:"Ludwig van Beethoven, il compositore",
na_dunja:"Dunja, la contadina russa",
na_wellington:"Arthur Wellesley, duca di Wellington",
na_napoleone:"Napoleone Bonaparte"
};
const GREET={
na_santu:"Salve, Pierpaolo, e non spaventare le capre: sono più nervose di me. Sono Santu, pastore, e se hai fame ho del brocciu fresco, se hai sete del latte, se hai fretta… qui no, qui il tempo cammina piano.",
na_bettina:"Salve, Pierpaolo, e parla piano: i miei bachi da seta sono pigri e si spaventano per niente. Sono Bettina, contadina, e in queste ceste c’è mezza fortuna della mia famiglia.",
na_denon:"Salve, Pierpaolo, e non muoverti: ho quasi finito il tuo naso. Sono Dominique Vivant Denon, e faccio il mestiere più scomodo del mondo: disegnare un paese intero mentre un esercito gli corre intorno.",
na_giuseppina:"Salve, Pierpaolo, e occhio alla rosa: ha le spine e un nome più lungo del tuo. Sono Giuseppina, e questo giardino è la cosa più bella che ho: i diamanti si perdono, i fiori tornano ogni primavera.",
na_gaspard:"Salve, Pierpaolo, e attento ai piedi: stamattina fa freddo e le scarpe, qui, valgono più dei galloni. Sono Gaspard, granatiere della Guardia e brontolone di professione: in francese, un «grognard».",
na_beethoven:"Salve, Pierpaolo, e parla forte, per favore: Vienna è piena di rumore e le mie orecchie hanno smesso di collaborare. Sono Ludwig van Beethoven, compositore: cioè uno che passa metà della vita a mettere in ordine i suoni e l’altra metà a cercare gli occhiali.",
na_dunja:"Salve, Pierpaolo, e togliti il cappello, che la mia izba è piccola: la stufa è quasi tutta la casa. Sono Dunja, e ho appena sfornato il pane, anche se in questi giorni non si sa per chi: i soldati passano, e il pane non basta mai.",
na_wellington:"Salve, Pierpaolo, e non fermarti nel fango: qui costa caro. Sono Arthur Wellesley, duca di Wellington, e oggi ho un solo obiettivo: restare dove sono fino a sera.",
na_napoleone:"Salve, Pierpaolo. Non ti alzare: a Longwood non si usa più, e di cerimonie ne ho avute abbastanza per due vite. Sono Napoleone, un tempo imperatore dei francesi, oggi un signore di campagna con una buona biblioteca e un clima da incubo."
};
const WNAME="Napoleone · Da Ajaccio a Sant’Elena";
const INTRO="Napoleone, dall’alba alla notte. Parti da Ajaccio, in Corsica, nell’anno 1769: un golfo, una casa ocra e un bambino che un giorno farà tremare l’Europa. Poi l’Italia e Tolone, dove un giovane generale scopre di essere bravo; l’Egitto, con le piramidi e una pietra scritta in tre modi; Parigi e un’incoronazione in cui l’imperatore si mette la corona da solo. Nel primo pomeriggio Austerlitz, nella nebbia e nel sole; poi Madrid, Saragozza e Vienna, dove un compositore si copre le orecchie con i cuscini. Nel tardo pomeriggio la Russia, con la neve, Mosca in fiamme e il ponte sulla Beresina. Alla sera Lipsia, l’isola d’Elba e Waterloo; di notte, su un’isola dell’Atlantico, un uomo ormai solo ripensa a tutto, e a Parigi, tanti anni dopo, le sue ceneri tornano a casa. Il tempo qui si piega: soldati, scienziati, contadini e imperatori di ogni anno ti vengono incontro.";
